package ec.edu.unl.sec.selfassessment.application;
import ec.edu.unl.sec.identityaccess.application.*;import ec.edu.unl.sec.identityaccess.domain.*;import ec.edu.unl.sec.selfassessment.domain.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProcessAssignmentService{private final SelfAssessmentRepository repository;private final CurrentActorPort actors;private final AuthorizationPort auth;private final FunctionalAssignmentPolicyPort policy;private final SelfAssessmentAuditService audit;public ProcessAssignmentService(SelfAssessmentRepository repository,CurrentActorPort actors,AuthorizationPort auth,FunctionalAssignmentPolicyPort policy,SelfAssessmentAuditService audit){this.repository=repository;this.actors=actors;this.auth=auth;this.policy=policy;this.audit=audit;}@Transactional public ProcessAssignment assign(UUID processId,long expected,UUID indicator,UUID identity,ProcessAssignment.Function function,Instant from,Instant to,String reason,UUID correlation){var p=repository.find(processId).orElseThrow(()->SelfAssessmentService.problem(ProcessProblemException.Kind.NOT_FOUND,"PROCESS_NOT_FOUND","El proceso no existe o no está visible."));var actor=actors.currentActor().orElseThrow(()->SelfAssessmentService.problem(ProcessProblemException.Kind.UNAUTHORIZED,"AUTHENTICATION_REQUIRED","Se requiere autenticación."));var scope=new AuthorizationScope(p.careerId(),p.id(),indicator);if(actor.technical()||!auth.isAllowed(actor.identityId(),OperationCode.PROCESS_COORDINATE,scope))throw SelfAssessmentService.problem(ProcessProblemException.Kind.FORBIDDEN,"PROCESS_SCOPE_DENIED","La operación no está permitida.");SelfAssessmentService.check(p,expected);if(p.state()==ProcessState.CLOSED)throw SelfAssessmentService.problem(ProcessProblemException.Kind.CONFLICT,"PROCESS_CLOSED","El proceso cerrado no admite cambios.");if(p.indicators().stream().noneMatch(i->i.id().equals(indicator)))throw SelfAssessmentService.problem(ProcessProblemException.Kind.INVALID,"INDICATOR_OUTSIDE_FIXED_MODEL","El indicador no pertenece al modelo fijado.");Instant processStart=p.periodStart().atStartOfDay(ZoneOffset.UTC).toInstant(),processEnd=p.periodEnd().plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();if(!from.isBefore(processEnd)||!to.isAfter(processStart))throw SelfAssessmentService.problem(ProcessProblemException.Kind.INVALID,"ASSIGNMENT_OUTSIDE_PERIOD","La vigencia no se superpone al período.");if(p.state()!=ProcessState.DRAFT&&(reason==null||reason.isBlank()))throw SelfAssessmentService.problem(ProcessProblemException.Kind.INVALID,"CRITICAL_CHANGE_REASON_REQUIRED","El cambio crítico requiere motivo.");var decision=policy.evaluate(identity,function.name(),scope,from,to);if(!decision.allowed())throw SelfAssessmentService.problem(ProcessProblemException.Kind.CONFLICT,decision.reasonCode(),"La asignación entra en conflicto con la política vigente.");var assignment=new ProcessAssignment(null,processId,indicator,identity,function,from,to,actor.identityId(),reason,null,0);repository.saveAssignment(assignment);audit.record(actor.identityId(),correlation,"PROCESS_ASSIGNMENT_CREATED",processId,"SUCCESS",null);return assignment;}@Transactional(readOnly=true)public List<ProcessAssignment> list(UUID id){return repository.assignments(id);}}
